import React, { useEffect, useState } from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer
} from 'recharts';

/* 
  transformContributionDays function from your original code 
  or import it from another file if you prefer.
*/
function transformContributionDays(weeks) {
  let days = [];
  weeks.forEach(week => {
    days = days.concat(week.contributionDays);
  });
  return days
    .map(day => ({ date: day.date, count: day.contributionCount }))
    .sort((a, b) => new Date(a.date) - new Date(b.date));
}

const MinimalPortfolio = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [isDesktop, setIsDesktop] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  // GitHub data
  const [contributionData, setContributionData] = useState([]);
  const [totalContributions, setTotalContributions] = useState(0);
  const [error, setError] = useState(null);

  useEffect(() => {
    document.title = 'Ranvir.';
    const timer = setTimeout(() => setIsVisible(true), 100);

    const handleResize = () => {
      setIsDesktop(window.innerWidth >= 768);
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    // Fetch GitHub contributions on mount
    fetchContributions();

    return () => {
      clearTimeout(timer);
      window.removeEventListener('resize', handleResize);
    };
  }, []);

  const fetchContributions = async () => {
    const toDate = new Date();
    const fromDate = new Date();
    fromDate.setFullYear(fromDate.getFullYear() - 1);
    const fromISO = fromDate.toISOString().split('T')[0] + 'T00:00:00Z';
    const toISO = toDate.toISOString().split('T')[0] + 'T23:59:59Z';

    const token = process.env.REACT_APP_GITHUB_TOKEN;
    if (!token) {
      setError(
        'GitHub token is not defined. Please set REACT_APP_GITHUB_TOKEN in your environment.'
      );
      return;
    }

    const query = `
      query {
        user(login: "ranvirdeshmukh") {
          contributionsCollection(from: "${fromISO}", to: "${toISO}") {
            contributionCalendar {
              totalContributions
              weeks {
                contributionDays {
                  date
                  contributionCount
                }
              }
            }
          }
        }
      }
    `;

    try {
      const response = await fetch('https://api.github.com/graphql', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `bearer ${token}`,
        },
        body: JSON.stringify({ query }),
      });
      const result = await response.json();

      if (result.errors) {
        throw new Error(result.errors.map(e => e.message).join(', '));
      }

      const calendar = result.data.user.contributionsCollection.contributionCalendar;
      setTotalContributions(calendar.totalContributions);
      const data = transformContributionDays(calendar.weeks);
      setContributionData(data);
    } catch (err) {
      console.error('Error fetching contributions:', err);
      setError(err.message);
    }
  };

  // Wrapper that spans the entire page
  const wrapperStyles = {
    background: darkMode
      ? 'linear-gradient(90deg, #1C093F 0%, #0C0F33 100%)'
      : '#f9f9f9',
    minHeight: '100vh',
    transition: 'background 0.3s ease, color 0.3s ease',
    position: 'relative'
  };

  // Main container for text content
  const containerStyles = {
    color: darkMode ? '#ffffff' : '#000000',
    fontFamily: "'SF Pro Display', sans-serif",
    fontWeight: 500,
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    margin: '0 auto',
    padding: '0 20px',
    maxWidth: isDesktop ? '800px' : '600px',
    minHeight: '100vh',
    transition: 'opacity 1s ease-in',
    position: 'relative',
    opacity: isVisible ? 1 : 0
  };

  const styles = {
    toggleContainer: {
      position: 'absolute',
      bottom: '20px',
      right: '20px',
      display: 'flex',
      alignItems: 'center',
      cursor: 'pointer',
      zIndex: 999,
    },
    toggleSwitch: {
      position: 'relative',
      width: '50px',
      height: '24px',
      backgroundColor: darkMode ? '#4cd137' : '#ccc',
      borderRadius: '12px',
      transition: 'background-color 0.3s',
    },
    toggleSwitchCircle: {
      position: 'absolute',
      top: '2px',
      left: darkMode ? '26px' : '2px',
      width: '20px',
      height: '20px',
      backgroundColor: '#fff',
      borderRadius: '50%',
      transition: 'left 0.3s',
    },
    toggleLabel: {
      marginLeft: '8px',
      fontSize: '0.9rem',
      color: darkMode ? '#ffffff' : '#000000',
    },
    name: {
      fontSize: isDesktop ? '48px' : '32px',
      margin: '0 0 10px 0',
      fontWeight: 500,
    },
    tagline: {
      fontSize: isDesktop ? '24px' : '20px',
      margin: '0 0 25px 0',
      opacity: 0.8,
    },
    description: {
      fontSize: isDesktop ? '18px' : '16px',
      lineHeight: '1.6',
      marginBottom: '30px',
    },
    dartmouthLink: {
      textDecoration: 'none',
      color: darkMode ? '#8bc34a' : '#00693e',
      fontWeight: 600,
    },
    linkContainer: {
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      marginBottom: '40px',
    },
    linkStyle: {
      textDecoration: 'none',
      color: darkMode ? '#ffffff' : '#000000',
      fontWeight: 500,
    },
    linkSeparator: {
      color: darkMode ? '#ffffff' : '#000000',
      opacity: 0.6,
    },
    bottomLogo: {
      marginTop: '40px',
      fontSize: isDesktop ? '16px' : '14px',
      fontWeight: 600,
      color: darkMode ? '#cccccc' : '#999999',
      opacity: 0.8,
      alignSelf: 'flex-start',
    },
  };

  return (
    <div style={wrapperStyles}>
      {/* Toggle for dark mode */}
      <div style={styles.toggleContainer} onClick={() => setDarkMode(prev => !prev)}>
        <div style={styles.toggleSwitch}>
          <div style={styles.toggleSwitchCircle}></div>
        </div>
        <span style={styles.toggleLabel}>Dark Mode</span>
      </div>

      {/* Main content */}
      <div style={containerStyles}>
        <h2 style={styles.name}>Ranvir Deshmukh</h2>
        <h3 style={styles.tagline}>I write software and make videos.</h3>

        <p style={styles.description}>
          I’m currently building{' '}
          <a
            href="https://courseme.ai"
            target="_blank"
            rel="noopener noreferrer"
            style={{
              textDecoration: 'none',
              color: darkMode ? '#c792ea' : '#571ce0',
              fontWeight: 600,
            }}
          >
            CourseMe
          </a>
          <span style={{ color: '#FD5E53', fontWeight: 600 }}>.</span> <br />
          Studying Computer Science at{' '}
          <a
            href="https://home.dartmouth.edu/"
            target="_blank"
            rel="noopener noreferrer"
            style={styles.dartmouthLink}
          >
            Dartmouth
          </a>
          . <br />
          Reach out — I’m always open to chat!
        </p>

        <div style={styles.linkContainer}>
          <a
            href="https://www.linkedin.com/in/ranvir-deshmukh-209706199/"
            style={styles.linkStyle}
            target="_blank"
            rel="noopener noreferrer"
          >
            LinkedIn
          </a>
          <span style={styles.linkSeparator}>|</span>
          <a
            href="https://github.com/Ranvirdeshmukh"
            style={styles.linkStyle}
            target="_blank"
            rel="noopener noreferrer"
          >
            GitHub
          </a>
        </div>

        {error && <p style={{ color: 'red' }}>Error: {error}</p>}
        <p>{totalContributions} contributions in the last year</p>

        <div style={styles.bottomLogo}>RD/&gt;</div>
      </div>

      {/* "Wave" chart at the bottom (footer). 
          Increase height if you want a taller wave.
      */}
      <footer 
        style={{ 
          width: '100%', 
          height: 250, 
          position: 'relative', 
          marginTop: '40px' 
        }}
      >
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={contributionData} margin={{ top: 0, right: 0, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="colorWave" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8} />
                <stop offset="95%" stopColor="#8884d8" stopOpacity={0} />
              </linearGradient>
            </defs>
            {/* Keep Tooltip so users can hover to see date + contributions */}
            <Tooltip />

            {/* Remove grid/axes for a clean wave, or keep them if you prefer. */}
            {/* <CartesianGrid strokeDasharray="3 3" /> */}
            {/* <XAxis dataKey="date" /> */}
            {/* <YAxis /> */}

            <Area
              type="monotoneX"
              dataKey="count"
              stroke="#8884d8"
              strokeWidth={2}
              fill="url(#colorWave)"
            />
          </AreaChart>
        </ResponsiveContainer>
      </footer>
    </div>
  );
};

export default MinimalPortfolio;
